export const SPELLING_LEVELS=['niko','roxy','kelly'];
export const SPELLING_TURN_WEIGHTS={niko:1,roxy:1.25,kelly:1.5};
export const SPELLING_MODES={bee:'Spelling Bee',builder:'Letter Builder',missing:'Missing Letters',sprint:'Spelling Sprint',survival:'Spelling Survival'};
export const SPELLING_DEFAULTS={pool:'niko',mode:'bee',layout:'solo',seconds:60,untimed:false,words:10,hints:true,music:.15,sound:.5,speech:.9,rate:.85,voiceId:'',board:true,pen:'#315e91',thickness:5,lines:true,autoClear:false};
export function normalizeSpellingSettings(value={}){const out={...SPELLING_DEFAULTS};for(const k of ['untimed','hints','board','lines','autoClear','practice'])if(typeof value[k]==='boolean')out[k]=value[k];for(const [k,min,max]of [['music',0,.5],['sound',0,1],['speech',0,1],['rate',.6,1.2],['thickness',2,16]])if(Number.isFinite(value[k]))out[k]=Math.max(min,Math.min(max,value[k]));for(const [k,options]of [['pool',SPELLING_LEVELS],['mode',Object.keys(SPELLING_MODES)],['layout',['solo','turns','split','coop']],['seconds',[30,60,90,120]],['words',[10,15,20]]])if(options.includes(value[k]))out[k]=value[k];if(/^#[0-9a-f]{6}$/i.test(value.pen||''))out.pen=value.pen;if(typeof value.voiceId==='string'&&value.voiceId.length<=400)out.voiceId=value.voiceId;if(typeof value.partner==='string'&&/^[a-zA-Z0-9_-]{1,140}$/.test(value.partner))out.partner=value.partner;return out;}
export function randomIndex(n,random=globalThis.crypto){if(n<1)return 0;if(typeof random==='function')return Math.min(n-1,Math.floor(random()*n));const limit=Math.floor(4294967296/n)*n,a=new Uint32Array(1);do random.getRandomValues(a);while(a[0]>=limit);return a[0]%n;}
export function shuffle(items,random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=randomIndex(i+1,random);[a[i],a[j]]=[a[j],a[i]];}return a;}
export const normalizeAnswer=s=>String(s||'').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ');
export function redactWord(text,word){return String(text||'').replace(new RegExp('\\b'+word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:s|es|ed|ing)?\\b','gi'),'[the word]');}
export function freshSpelling(){return{version:1,settings:{...SPELLING_DEFAULTS},pools:{},games:0,correct:0,wrong:0,bestScore:0,bestStreak:0,categories:{}};}
export function poolProgress(progress,pool){progress.pools??={};return progress.pools[pool]??=( {history:[],lastLineup:'',words:{},recentAnswers:[],sessions:0});}
export const nikoWordEligible=w=>w.word.length>=3&&w.word.length<=6;
// Each ten-word block is a shuffled mix: 3 short, 4 medium, 2 longer, 1 six-letter word.
export function mixNikoLengths(sorted,random){const eligible=sorted.filter(nikoWordEligible),buckets=new Map([3,4,5,6].map(n=>[n,eligible.filter(w=>w.word.length===n)])),out=[];while(out.length<eligible.length){for(const length of shuffle([3,4,3,5,4,6,3,4,5,4],random)){const word=buckets.get(length).shift();if(word)out.push(word);}}return out;}
export function chooseDeck(words,progress,{random,practice=false,pool=words[0]?.pool}={}){const recent=new Map(progress.history.map((w,i)=>[w,i])),correct=progress.recentAnswers||[],tier=correct.length>=12&&correct.slice(-20).filter(Boolean).length/correct.slice(-20).length>.85?3:correct.length>=8&&correct.slice(-20).filter(Boolean).length/correct.slice(-20).length>=.65?2:1;let candidates=practice?words.filter(w=>(progress.words[w.word]?.missed||0)>0&&(progress.words[w.word]?.reviewNeeded!==false)):words;
 if(pool==='niko'&&!practice)candidates=candidates.filter(nikoWordEligible);
 let shuffled=shuffle(candidates,random);shuffled.sort((a,b)=>{const ar=recent.has(a.word),br=recent.has(b.word);if(ar!==br)return ar?1:-1;if(ar&&br)return recent.get(a.word)-recent.get(b.word);return Math.abs(a.tier-tier)-Math.abs(b.tier-tier);});if(pool==='niko'&&!practice)shuffled=mixNikoLengths(shuffled,random);if(shuffled.length>1&&shuffled.slice(0,10).map(w=>w.word).join('|')===progress.lastLineup){[shuffled[0],shuffled[1]]=[shuffled[1],shuffled[0]];}progress.lastLineup=shuffled.slice(0,10).map(w=>w.word).join('|');return shuffled;}
export function encounterWord(progress,word,poolSize){progress.history=progress.history.filter(w=>w!==word);progress.history.push(word);if(progress.history.length>poolSize)progress.history.splice(0,progress.history.length-poolSize);}
export function recordSpellingAnswer(state,pool,word,{correct,hinted,sessionId,category='Words'}){const p=poolProgress(state,pool),r=Object.hasOwn(p.words,word)?p.words[word]:(p.words[word]={attempts:0,correct:0,missed:0,unhintedSessions:[],mastered:false,reviewNeeded:false});r.attempts++;if(correct){r.correct++;state.correct++;if(!hinted){if(!r.unhintedSessions.includes(sessionId))r.unhintedSessions.push(sessionId);r.unhintedSessions=r.unhintedSessions.slice(-3);if(r.unhintedSessions.length>=3)r.mastered=true;r.reviewNeeded=false;}}else{r.missed++;state.wrong++;r.reviewNeeded=true;}p.recentAnswers.push(correct);p.recentAnswers=p.recentAnswers.slice(-20);state.categories??={};const c=state.categories[category]??={correct:0,wrong:0};c[correct?'correct':'wrong']++;return r;}
export function answerDiff(typed,expected){const a=[...typed],b=[...expected],dp=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=0;i<=a.length;i++)dp[i][0]=i;for(let j=0;j<=b.length;j++)dp[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(a[i-1]===b[j-1]?0:1));let i=a.length,j=b.length,out=[];while(i||j){if(i&&j&&dp[i][j]===dp[i-1][j-1]+(a[i-1]===b[j-1]?0:1)){out.push({typed:a[--i],expected:b[--j],kind:a[i]===b[j]?'match':'replace'});}else if(j&&dp[i][j]===dp[i][j-1]+1)out.push({typed:'',expected:b[--j],kind:'missing'});else out.push({typed:a[--i],expected:'',kind:'extra'});}return out.reverse();}
export class SpellingRun{
 constructor({words,progress,pool='niko',mode='bee',sessionId,random,practice=false,seconds=60,untimed=false,target=10,turnBased=false,deferStart=false,onEncounter=()=>{},onAnswer=()=>{}}){Object.assign(this,{pool,mode,sessionId,random,onEncounter,onAnswer,seconds,untimed,target,turnBased});this.deck=chooseDeck(words,progress,{random,practice,pool});this.originalDeck=[...this.deck];this.index=-1;this.clock=0;this.wordAt=0;this.score=0;this.baseScore=0;this.correct=0;this.wrong=0;this.streak=0;this.bestStreak=0;this.hearts=3;this.done=false;this.feedback=null;this.results=[];if(!deferStart)this.next();}
 next(){if(this.done)return;if(this.index>=0&&this.feedback===null)return false;if(this.feedback&&(this.turnBased?this.correct+this.wrong>=this.target:this.mode==='survival'&&this.hearts===0||this.mode!=='survival'&&!(this.mode==='sprint'&&!this.untimed)&&this.correct+this.wrong>=this.target)){this.done=true;return false;}this.index++;if(this.turnBased&&this.originalDeck.length&&this.index>=this.deck.length)this.deck.push(...shuffle(this.originalDeck,this.random));if(this.index>=this.deck.length){this.done=true;this.reason=this.deck.length?'You explored every word in this session.':'No missed words need review yet. Try Spelling Bee.';return false;}if(this.mode==='survival'&&this.pool!=='niko'){const tier=Math.min(3,1+Math.floor(this.correct/8)),j=this.deck.findIndex((w,k)=>k>=this.index&&w.tier===tier);if(j>=this.index)[this.deck[this.index],this.deck[j]]=[this.deck[j],this.deck[this.index]];}this.entry=this.deck[this.index];this.wordAt=this.clock;this.hinted=false;this.answer='';this.feedback=null;this.blankIndices=[];if(this.mode==='missing'){const count=Math.max(1,Math.ceil(this.entry.word.length*(this.pool==='niko'?.2:this.pool==='roxy'?.3:.4)));this.blankIndices=shuffle([...this.entry.word].map((_,i)=>i),this.random).slice(0,count).sort((a,b)=>a-b);}const extras=Array.from({length:Math.min(4,Math.ceil(this.entry.word.length/3))},()=>String.fromCharCode(97+randomIndex(26,this.random)));this.tiles=shuffle([...this.entry.word,...extras].map((letter,id)=>({id,letter})),this.random);this.placed=[];this.onEncounter(this.entry);return true;}
 get expected(){return this.mode==='missing'?this.blankIndices.map(i=>this.entry.word[i]).join(''):this.entry.word;}
 get prompt(){return this.mode==='missing'?[...this.entry.word].map((c,i)=>this.blankIndices.includes(i)?'＿':c.toUpperCase()).join(' '):'Listen, imagine, spell.';}
 get remaining(){return Math.max(0,this.seconds*1000-(this.turnBased?this.clock-this.wordAt:this.clock));}
 get accuracy(){const n=this.correct+this.wrong;return n?Math.round(this.correct/n*100):0;}
 hint(){this.hinted=true;return this.entry.hint||this.entry.pattern+' · '+this.entry.word.length+' letters. First letter: '+this.entry.word[0].toUpperCase();}
 placeTile(id,at=this.placed.length){if(this.feedback||this.done)return;const old=this.placed.indexOf(id);if(old>=0)this.placed.splice(old,1);if(!this.tiles.some(t=>t.id===id))return;this.placed.splice(Math.max(0,Math.min(at,this.placed.length)),0,id);this.syncTiles();}
 removeTile(at){if(this.feedback||this.done)return;this.placed.splice(at,1);this.syncTiles();}
 syncTiles(){this.answer=this.placed.map(id=>this.tiles.find(t=>t.id===id).letter).join('');}
 key(letter){if(this.feedback||this.done)return;if(this.mode==='builder'){if(letter==='Backspace')this.removeTile(this.placed.length-1);else{const tile=this.tiles.find(t=>t.letter===letter.toLowerCase()&&!this.placed.includes(t.id));if(tile)this.placeTile(tile.id);}}else this.answer=letter==='Backspace'?this.answer.slice(0,-1):letter==='Clear'?'':(this.answer+letter.toLowerCase()).slice(0,40);}
 submit(value=this.answer,{timedOut=false}={}){if(this.done||this.feedback)return null;const typed=normalizeAnswer(value);if(!typed)return null;const correct=typed===normalizeAnswer(this.expected);let points=0;if(correct){this.correct++;this.streak++;this.bestStreak=Math.max(this.bestStreak,this.streak);points=100+(this.hinted?0:25)+({3:50,5:100,10:250}[this.streak]||0);if(this.mode==='sprint')points+=Math.max(0,20-Math.floor((this.clock-(this.wordAt||0))/1000));this.baseScore+=points;const adjusted=Math.round(this.baseScore*(this.turnBased?SPELLING_TURN_WEIGHTS[this.pool]:1));points=adjusted-this.score;this.score=adjusted;}else{this.wrong++;this.streak=0;if(this.mode==='survival')this.hearts=Math.max(0,this.hearts-1);}
 this.feedback={correct,typed,expected:this.expected,word:this.entry.word,points,timedOut,multiplier:this.turnBased?SPELLING_TURN_WEIGHTS[this.pool]:1,hinted:this.hinted,diff:answerDiff(typed,this.expected),entry:this.entry};this.results.push(this.feedback);this.onAnswer(this.feedback);return this.feedback;}
 update(dt){if(this.done||this.turnBased&&this.feedback)return;this.clock+=Math.max(0,Math.min(1000,dt));if(this.mode==='sprint'&&!this.untimed&&this.remaining===0){if(this.turnBased)this.submit('[time expired]',{timedOut:true});else{this.done=true;this.reason='Time to celebrate your spelling.';}}}
 summary(){return{pool:this.pool,mode:this.mode,score:this.score,baseScore:this.baseScore,multiplier:this.turnBased?SPELLING_TURN_WEIGHTS[this.pool]:1,correct:this.correct,wrong:this.wrong,accuracy:this.accuracy,bestStreak:this.bestStreak,clock:this.clock,attempted:this.correct+this.wrong,completed:this.done,hearts:this.hearts};}
}
